        $preprocessor = new TextPreprocessor();
        foreach ($thesisData as $th) {
            $studId = $nimToId[$th['nim']] ?? null;
            if (!$studId) continue;
            $preprocessed = implode(' ', $preprocessor->preprocess($th['title']));
            $this->db->table('thesis')->insert([
                'student_id'       => $studId,
                'category_id'      => $th['category_id'],
                'title'            => $th['title'],
                'year'             => $th['year'],
                'preprocessed_text' => $preprocessed,
                'created_at'       => date('Y-m-d H:i:s'),
                'updated_at'       => date('Y-m-d H:i:s'),
            ]);
        }

        // ── 5. PENGATURAN AMBANG BATAS ────────────────────────────────
        $this->db->table('system_settings')->insert([
            'cosine_weight'          => 0.60,
            'jaccard_weight'         => 0.40,
            'similar_threshold'      => 0.75,
            'review_threshold'       => 0.40,
            'max_similarity_results' => 5,
        ]);

        // ── 6. RIWAYAT PENGECEKAN (perhitungan nyata) ─────────────────
        $this->db->table('similarity_checks')->truncate();
        $this->db->table('similarity_check_details')->truncate();

        helper('uuid');

        $thesisCollection = $this->db->table('thesis tt')
            ->select('tt.id, tt.title, tt.preprocessed_text, s.student_id AS nim, s.name AS student_name, tc.category_name, tt.year')
            ->join('students s', 's.id = tt.student_id')
            ->join('topic_categories tc', 'tc.id = tt.category_id')
            ->get()
            ->getResultArray();

        $threshold = $this->db->table('system_settings')->get()->getRowArray();

        $calculator   = new SimilarityCalculator();
        $users        = $this->db->table('users')->where('role', 'user')->get()->getResultArray();

        $seedChecks = [
            'Sistem Deteksi Dini Penyakit Pencernaan Menggunakan Metode Certainty Factor Berbasis Web',
            'Aplikasi Prediksi Harga Emas Menggunakan Algoritma Extreme Gradient Boosting',
            'Klasterisasi Hasil Produksi Tanaman Pangan Menggunakan Algoritma K-Medoids',
            'Sistem Informasi Geografis Pemetaan Lokasi Banjir di Kota Lhokseumawe Berbasis Web',
            'Rekomendasi Pemilihan Lokasi Usaha UMKM Menggunakan Metode AHP dan TOPSIS',
            'Penerapan Metode Least Square Untuk Memprediksi Stok Obat Pada Puskesmas',
            'Analisis Sentimen Terhadap Boikot Produk di Media Sosial Menggunakan LSTM',
            'Sistem Smart Irigasi Untuk Tanaman Cabai Berbasis IoT Dengan Metode Fuzzy',
        ];

        foreach ($seedChecks as $i => $inputTitle) {
            $results = $calculator->runCheck(
                $inputTitle,
                $thesisCollection,
                $threshold,
                $preprocessor
            );

            $maxResults = (int) ($threshold['max_similarity_results'] ?? 5);
            $results    = array_slice($results, 0, $maxResults);

            $uuid    = generate_uuid();
            $userId  = $users[$i % count($users)]['id'];
            $checked = date('Y-m-d H:i:s', strtotime('-' . (count($seedChecks) - $i) . ' days'));

            $this->db->table('similarity_checks')->insert([
                'user_id'     => $userId,
                'uuid'        => $uuid,
                'input_title' => $inputTitle,
                'checked_at'  => $checked,
            ]);

            $checkId = $this->db->insertID();

            $details = array_map(fn($r) => [
                'check_id'        => $checkId,
                'thesis_id'       => $r['thesis_id'],
                'cosine_score'    => $r['cosine_score'],
                'jaccard_score'   => $r['jaccard_score'],
                'hybrid_score'    => $r['hybrid_score'],
                'result_category' => $r['result_category'],
            ], $results);

            $this->db->table('similarity_check_details')->insertBatch($details);
        }

        $this->db->query('SET FOREIGN_KEY_CHECKS = 1');
    }
